from pathlib import Path

path = Path('index.html')
text = path.read_text()

old_header = '''                    <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1 px-1 mb-2">\n                        <span class="text-[10px] font-black uppercase tracking-[0.18em] text-gray-500">Quick Launch</span>\n                        <span class="text-xs text-gray-400">Open a company directly in SethiStock.</span>\n                    </div>'''
new_header = '''                    <div class="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1 px-1 mb-2">\n                        <span class="text-[10px] font-black uppercase tracking-[0.18em] text-gray-500">Quick Launch</span>\n                        <button id="command-palette-trigger" type="button" class="inline-flex items-center gap-2 self-start rounded-lg text-xs font-semibold text-gray-400 transition hover:text-blue-600 sm:self-auto">\n                            Search platform\n                            <kbd id="command-shortcut" class="rounded-md border border-gray-200 bg-gray-50 px-1.5 py-0.5 text-[10px] font-bold text-gray-500">Ctrl K</kbd>\n                        </button>\n                    </div>'''
if text.count(old_header) != 1:
    raise SystemExit(f'Quick Launch header expected once, found {text.count(old_header)}')
text = text.replace(old_header, new_header, 1)

modal_anchor = '''    <div id="login-modal" class="hidden fixed inset-0 z-[100] items-center justify-center bg-gray-950/55 px-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-labelledby="admin-login-title">'''
command_modal = '''    <div id="command-palette" class="hidden fixed inset-0 z-[110] items-start justify-center bg-gray-950/45 px-4 pt-[12vh] backdrop-blur-sm" role="dialog" aria-modal="true" aria-labelledby="command-palette-title">\n        <div class="w-full max-w-2xl overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-2xl">\n            <div class="border-b border-gray-100 p-3">\n                <div class="flex items-center gap-3 rounded-xl bg-gray-50 px-4 py-3">\n                    <svg class="h-5 w-5 shrink-0 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="m21 21-4.35-4.35m1.35-5.65a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z"></path></svg>\n                    <label id="command-palette-title" for="command-palette-input" class="sr-only">Search SethiWay</label>\n                    <input id="command-palette-input" type="text" autocomplete="off" spellcheck="false" placeholder="Search tools, sections or enter a ticker" class="min-w-0 flex-1 bg-transparent text-sm font-semibold text-gray-900 outline-none placeholder:font-medium placeholder:text-gray-400">\n                    <kbd class="rounded-md border border-gray-200 bg-white px-2 py-1 text-[10px] font-bold text-gray-400">Esc</kbd>\n                </div>\n            </div>\n            <div id="command-palette-results" class="max-h-[52vh] overflow-y-auto p-2"></div>\n            <div class="flex flex-wrap items-center justify-between gap-2 border-t border-gray-100 px-4 py-2.5 text-[10px] font-semibold text-gray-400">\n                <span>Type a ticker to open it in SethiStock.</span>\n                <span class="hidden sm:inline">↑ ↓ move · Enter open · Esc close</span>\n            </div>\n        </div>\n    </div>\n\n'''
if text.count(modal_anchor) != 1:
    raise SystemExit(f'Login modal anchor expected once, found {text.count(modal_anchor)}')
text = text.replace(modal_anchor, command_modal + modal_anchor, 1)

js_anchor = '''    const adminModal = document.getElementById('login-modal');'''
command_js = '''    const commandPalette = document.getElementById('command-palette');\n    const commandPaletteTrigger = document.getElementById('command-palette-trigger');\n    const commandPaletteInput = document.getElementById('command-palette-input');\n    const commandPaletteResults = document.getElementById('command-palette-results');\n    const commandShortcut = document.getElementById('command-shortcut');\n    let commandSelection = 0;\n    let visibleCommands = [];\n\n    const platformCommands = [\n        { tool: 'SethiMacro', label: 'Open SethiMacro', detail: 'Macro dashboard', href: 'sethimacro.html', keywords: 'macro economy dashboard' },\n        { tool: 'SethiMacro', label: 'Job Market', detail: 'Employment and labour data', href: 'sethimacro.html#job-market', keywords: 'jobs employment labour unemployment' },\n        { tool: 'SethiMacro', label: 'Inflation & Rates', detail: 'Inflation, yields and central banks', href: 'sethimacro.html#inflation-rates', keywords: 'inflation rates yields central bank' },\n        { tool: 'SethiMacro', label: 'Currencies', detail: 'FX and currency indicators', href: 'sethimacro.html#currencies', keywords: 'fx currency currencies' },\n        { tool: 'SethiStock', label: 'Open SethiStock', detail: 'Single-equity analysis', href: 'sethistock.html', keywords: 'stock equity company security' },\n        { tool: 'SethiStock', label: 'Key Metrics', detail: 'Fundamentals and market statistics', href: 'sethistock.html#key-metrics', keywords: 'metrics fundamentals statistics stock' },\n        { tool: 'SethiStock', label: 'Research Labs', detail: 'Earnings reactions and valuation history', href: 'sethistock.html#research-labs', keywords: 'research earnings valuation history' },\n        { tool: 'SethiStock', label: 'Valuations', detail: 'DCF and valuation tools', href: 'sethistock.html#valuation', keywords: 'valuation dcf intrinsic value' },\n        { tool: 'SethiPortfolio', label: 'Open SethiPortfolio', detail: 'Portfolio management', href: 'sethiportfolio.html', keywords: 'portfolio holdings performance' },\n        { tool: 'SethiPortfolio', label: 'Performance', detail: 'Returns and benchmarks', href: 'sethiportfolio.html#performance', keywords: 'portfolio performance returns benchmark' },\n        { tool: 'SethiPortfolio', label: 'Portfolio Lab', detail: 'Exposure, FX and risk analysis', href: 'sethiportfolio.html#portfolio-lab', keywords: 'portfolio lab exposure fx risk' },\n        { tool: 'SethiPortfolio', label: 'Exposure Map', detail: 'Sector, currency and geography exposure', href: 'sethiportfolio.html#exposure', keywords: 'sector currency geography exposure' },\n        { tool: 'SethiPortfolio', label: 'FX Analytics', detail: 'Sterling and translation effects', href: 'sethiportfolio.html#fx', keywords: 'fx sterling currency translation' },\n        { tool: 'SethiPortfolio', label: 'Portfolio Risk', detail: 'Concentration and risk contribution', href: 'sethiportfolio.html#risk', keywords: 'portfolio risk concentration correlation var' },\n        { tool: 'SethiPortfolio', label: 'Decisions', detail: 'Investment journal and portfolio changes', href: 'sethiportfolio.html#decisions', keywords: 'decisions journal changes rationale' },\n        { tool: 'SethiQuant', label: 'Open SethiQuant', detail: 'Quantitative and risk terminal', href: 'sethiquant.html', keywords: 'quant quantitative terminal' },\n        { tool: 'SethiQuant', label: 'Options & Greeks', detail: 'Option pricing and sensitivities', href: 'sethiquant.html#section-options', keywords: 'options greeks derivatives pricing' },\n        { tool: 'SethiQuant', label: 'Backtesting', detail: 'Strategy testing', href: 'sethiquant.html#section-backtest', keywords: 'backtest backtesting strategy' },\n        { tool: 'SethiQuant', label: 'Market Risk Lab', detail: 'VaR, stress tests and risk attribution', href: 'sethiquant.html#section-var', keywords: 'market risk var stress correlation attribution' }\n    ];\n\n    const commandToolTone = {\n        SethiMacro: 'text-red-600 bg-red-50 border-red-100',\n        SethiStock: 'text-emerald-700 bg-emerald-50 border-emerald-100',\n        SethiPortfolio: 'text-amber-700 bg-amber-50 border-amber-100',\n        SethiQuant: 'text-blue-700 bg-blue-50 border-blue-100'\n    };\n\n    function commandSearchText(command) {\n        return `${command.tool} ${command.label} ${command.detail} ${command.keywords || ''}`.toLowerCase();\n    }\n\n    function buildVisibleCommands(query) {\n        const clean = query.trim();\n        const lower = clean.toLowerCase();\n        const matches = platformCommands\n            .filter(command => !lower || commandSearchText(command).includes(lower))\n            .slice(0, 8);\n\n        const ticker = clean.toUpperCase();\n        if (clean && /^[A-Z0-9.^-]{1,20}$/.test(ticker)) {\n            matches.push({\n                tool: 'SethiStock',\n                label: `Analyse ${ticker}`,\n                detail: 'Open ticker directly in SethiStock',\n                href: `sethistock.html?ticker=${encodeURIComponent(ticker)}&source=command-palette`,\n                tickerAction: true\n            });\n        }\n        return matches;\n    }\n\n    function renderCommandPaletteResults() {\n        visibleCommands = buildVisibleCommands(commandPaletteInput.value);\n        if (commandSelection >= visibleCommands.length) commandSelection = Math.max(0, visibleCommands.length - 1);\n        commandPaletteResults.replaceChildren();\n\n        if (!visibleCommands.length) {\n            const empty = document.createElement('p');\n            empty.className = 'px-4 py-8 text-center text-sm font-semibold text-gray-400';\n            empty.textContent = 'No matching tool or section.';\n            commandPaletteResults.appendChild(empty);\n            return;\n        }\n\n        visibleCommands.forEach((command, index) => {\n            const button = document.createElement('button');\n            button.type = 'button';\n            button.dataset.index = String(index);\n            button.className = `flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left transition ${index === commandSelection ? 'bg-gray-100' : 'hover:bg-gray-50'}`;\n\n            const badge = document.createElement('span');\n            badge.className = `shrink-0 rounded-md border px-2 py-1 text-[9px] font-black uppercase tracking-wider ${commandToolTone[command.tool] || 'text-gray-600 bg-gray-50 border-gray-200'}`;\n            badge.textContent = command.tool.replace('Sethi', '');\n\n            const copy = document.createElement('span');\n            copy.className = 'min-w-0 flex-1';\n            const title = document.createElement('span');\n            title.className = 'block truncate text-sm font-black text-gray-900';\n            title.textContent = command.label;\n            const detail = document.createElement('span');\n            detail.className = 'mt-0.5 block truncate text-xs text-gray-400';\n            detail.textContent = command.detail;\n            copy.append(title, detail);\n\n            const arrow = document.createElement('span');\n            arrow.className = 'shrink-0 text-sm font-bold text-gray-300';\n            arrow.textContent = '→';\n            button.append(badge, copy, arrow);\n            button.addEventListener('mouseenter', () => { commandSelection = index; renderCommandPaletteResults(); });\n            button.addEventListener('click', () => openCommand(index));\n            commandPaletteResults.appendChild(button);\n        });\n    }\n\n    function openCommand(index = commandSelection) {\n        const command = visibleCommands[index];\n        if (!command) return;\n        window.location.href = command.href;\n    }\n\n    function openCommandPalette() {\n        commandPalette.classList.remove('hidden');\n        commandPalette.classList.add('flex');\n        commandPaletteInput.value = '';\n        commandSelection = 0;\n        renderCommandPaletteResults();\n        setTimeout(() => commandPaletteInput.focus(), 0);\n    }\n\n    function closeCommandPalette() {\n        commandPalette.classList.add('hidden');\n        commandPalette.classList.remove('flex');\n    }\n\n    commandShortcut.textContent = /Mac|iPhone|iPad/.test(navigator.platform) ? '⌘ K' : 'Ctrl K';\n    commandPaletteTrigger.addEventListener('click', openCommandPalette);\n    commandPalette.addEventListener('click', event => {\n        if (event.target === commandPalette) closeCommandPalette();\n    });\n    commandPaletteInput.addEventListener('input', () => {\n        commandSelection = 0;\n        renderCommandPaletteResults();\n    });\n    commandPaletteInput.addEventListener('keydown', event => {\n        if (event.key === 'ArrowDown') {\n            event.preventDefault();\n            if (visibleCommands.length) commandSelection = (commandSelection + 1) % visibleCommands.length;\n            renderCommandPaletteResults();\n        } else if (event.key === 'ArrowUp') {\n            event.preventDefault();\n            if (visibleCommands.length) commandSelection = (commandSelection - 1 + visibleCommands.length) % visibleCommands.length;\n            renderCommandPaletteResults();\n        } else if (event.key === 'Enter') {\n            event.preventDefault();\n            openCommand();\n        }\n    });\n    document.addEventListener('keydown', event => {\n        if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') {\n            event.preventDefault();\n            if (commandPalette.classList.contains('hidden')) openCommandPalette();\n            else closeCommandPalette();\n        } else if (event.key === 'Escape' && !commandPalette.classList.contains('hidden')) {\n            closeCommandPalette();\n        }\n    });\n\n'''
if text.count(js_anchor) != 1:
    raise SystemExit(f'Admin JS anchor expected once, found {text.count(js_anchor)}')
text = text.replace(js_anchor, command_js + js_anchor, 1)

old_recent = '''                <div class="grid grid-cols-1 md:grid-cols-3 gap-4">\n                    <a href="#top" class="group rounded-2xl border border-gray-200 bg-white p-5 shadow-sm hover:border-blue-200 hover:shadow-md transition">\n                        <div class="flex items-center justify-between gap-3">\n                            <span class="text-[10px] font-black uppercase tracking-[0.16em] text-gray-400">Hub</span>\n                            <span class="text-blue-600 group-hover:translate-x-0.5 transition-transform">→</span>\n                        </div>\n                        <h3 class="mt-3 text-lg font-black text-gray-950">Continue Shortcut</h3>\n                        <p class="mt-2 text-sm leading-relaxed text-gray-500">Return to the last SethiWay tool, stock or section you were using.</p>\n                    </a>\n\n                    <a href="#top" class="group rounded-2xl border border-gray-200 bg-white p-5 shadow-sm hover:border-blue-200 hover:shadow-md transition">\n                        <div class="flex items-center justify-between gap-3">\n                            <span class="text-[10px] font-black uppercase tracking-[0.16em] text-gray-400">Hub</span>\n                            <span class="text-blue-600 group-hover:translate-x-0.5 transition-transform">→</span>\n                        </div>\n                        <h3 class="mt-3 text-lg font-black text-gray-950">Watchlist Shortcuts</h3>\n                        <p class="mt-2 text-sm leading-relaxed text-gray-500">Saved SethiStock tickers now appear inside Quick Launch for one-click access.</p>\n                    </a>\n\n                    <a href="#top" class="group rounded-2xl border border-gray-200 bg-white p-5 shadow-sm hover:border-blue-200 hover:shadow-md transition">\n                        <div class="flex items-center justify-between gap-3">\n                            <span class="text-[10px] font-black uppercase tracking-[0.16em] text-gray-400">Hub</span>\n                            <span class="text-blue-600 group-hover:translate-x-0.5 transition-transform">→</span>\n                        </div>\n                        <h3 class="mt-3 text-lg font-black text-gray-950">Quick Launch</h3>\n                        <p class="mt-2 text-sm leading-relaxed text-gray-500">Enter a ticker on the homepage and open it directly in SethiStock.</p>\n                    </a>\n                </div>'''
new_recent = '''                <div class="grid grid-cols-1 md:grid-cols-3 gap-4">\n                    <button type="button" onclick="openCommandPalette()" class="group rounded-2xl border border-gray-200 bg-white p-5 text-left shadow-sm hover:border-blue-200 hover:shadow-md transition">\n                        <div class="flex items-center justify-between gap-3">\n                            <span class="text-[10px] font-black uppercase tracking-[0.16em] text-gray-400">Hub</span>\n                            <span class="text-blue-600 group-hover:translate-x-0.5 transition-transform">→</span>\n                        </div>\n                        <h3 class="mt-3 text-lg font-black text-gray-950">Command Palette</h3>\n                        <p class="mt-2 text-sm leading-relaxed text-gray-500">Use Ctrl or Cmd + K to jump to a tool, section or ticker.</p>\n                    </button>\n\n                    <a href="#top" class="group rounded-2xl border border-gray-200 bg-white p-5 shadow-sm hover:border-blue-200 hover:shadow-md transition">\n                        <div class="flex items-center justify-between gap-3">\n                            <span class="text-[10px] font-black uppercase tracking-[0.16em] text-gray-400">Hub</span>\n                            <span class="text-blue-600 group-hover:translate-x-0.5 transition-transform">→</span>\n                        </div>\n                        <h3 class="mt-3 text-lg font-black text-gray-950">Continue Shortcut</h3>\n                        <p class="mt-2 text-sm leading-relaxed text-gray-500">Return to the last SethiWay tool, stock or section you were using.</p>\n                    </a>\n\n                    <a href="#top" class="group rounded-2xl border border-gray-200 bg-white p-5 shadow-sm hover:border-blue-200 hover:shadow-md transition">\n                        <div class="flex items-center justify-between gap-3">\n                            <span class="text-[10px] font-black uppercase tracking-[0.16em] text-gray-400">Hub</span>\n                            <span class="text-blue-600 group-hover:translate-x-0.5 transition-transform">→</span>\n                        </div>\n                        <h3 class="mt-3 text-lg font-black text-gray-950">Watchlist Shortcuts</h3>\n                        <p class="mt-2 text-sm leading-relaxed text-gray-500">Saved SethiStock tickers now appear inside Quick Launch for one-click access.</p>\n                    </a>\n                </div>'''
if text.count(old_recent) != 1:
    raise SystemExit(f'Recently Added grid expected once, found {text.count(old_recent)}')
text = text.replace(old_recent, new_recent, 1)

for marker in ['id="command-palette"', 'id="command-palette-input"', 'function openCommandPalette()', '>Command Palette</h3>']:
    if text.count(marker) != 1:
        raise SystemExit(f'Missing or duplicated marker: {marker}')
if '—' in text:
    raise SystemExit('Em dash remains in homepage copy')

path.write_text(text)
